/* Generated by gen_packs.py from the original data files: pack "toafk". */
MC.registerPack({"id":"toafk","cards":[{"id":"11001","name":"캉 (정복자)","en":"* Kang (The Conqueror)","type":"villain","enc":true,"set":"Kang","unique":true,"hp":12,"hpStar":true,"atk":2,"sch":1,"stage":1,"tr":["TEMPORAL"],"toughness":1,"traits":["시간"],"text":"강인\n[star] <b>강제 난입</b>: 캉이 당신을 공격할 때, 주요 음모에 위협을 1만큼 놓거나, 그가 이 공격에 대해 공격 +2를 받는 것 중 하나를 선택합니다.\n<b>격파될 때</b>: 페이즈가 끝날 때 주요 음모를 스테이지 2로 진행합니다.","star":true},{"id":"11002","name":"캉 (이모터스)","en":"* Kang (Immortus)","type":"villain","enc":true,"set":"Kang","unique":true,"hp":18,"atk":2,"sch":2,"stage":2,"tr":["TEMPORAL"],"toughness":1,"traits":["시간"],"text":"강인.\n하수인이 플레이 영역에 있는 동안 이 빌런은 피해를 입을 수 없습니다.\n<b>격파될 때</b>: 크로노폴리스를 게임에서 제거합니다. 페이즈가 끝날 때, 다른 게임 영역에 합류합니다."},{"id":"11003","name":"캉 (아이언 래드)","en":"* Kang (Iron Lad)","type":"villain","enc":true,"set":"Kang","unique":true,"hp":18,"atk":2,"sch":1,"stage":2,"retaliate":1,"tr":["TEMPORAL"],"toughness":1,"traits":["시간"],"text":"반격 1. 강인.\n<b>격파될 때</b>: 피할 수 없는 운명을 게임에서 제거합니다. 페이즈가 끝날 때, 다른 게임 영역에 합류합니다."},{"id":"11004","name":"캉 (라마-투트)","en":"* Kang (Rama-Tut)","type":"villain","enc":true,"set":"Kang","unique":true,"hp":18,"atk":2,"sch":1,"stage":2,"tr":["TEMPORAL"],"toughness":1,"traits":["시간"],"text":"강인.\n[star] 이 빌런은 플레이 영역에 있는 의무 카드마다 공격 +1을 받습니다.\n<b>격파될 때</b>: 라마-투트의 왕국을 게임에서 제거합니다. 페이즈가 끝날 때, 다른 게임 영역에 합류합니다.","star":true},{"id":"11005","name":"캉 (스칼렛 센추리온)","en":"* Kang (Scarlet Centurion)","type":"villain","enc":true,"set":"Kang","unique":true,"hp":18,"atk":3,"sch":0,"stage":2,"tr":["TEMPORAL"],"toughness":1,"traits":["시간"],"text":"강인.\n[star] 이 빌런의 공격은 관통을 얻습니다.\n<b>격파될 때</b>: 현재와 미래의 전쟁을 게임에서 제거합니다. 페이즈가 끝날 때, 다른 게임 영역에 합류합니다.","star":true},{"id":"11006","name":"캉 (정복자)","en":"* Kang (The Conqueror)","type":"villain","enc":true,"set":"Kang","unique":true,"hp":20,"hpStar":true,"atk":2,"sch":2,"stage":3,"tr":["TEMPORAL"],"toughness":1,"traits":["시간"],"text":"강인.\n[star] <b>강제 난입</b>: 캉이 당신을 공격할 때, 주요 음모에 위협을 1만큼 놓거나, 그가 이 공격에 대해 공격 +2를 받는 것 중 하나를 선택합니다.\n<b>격파될 때</b>: 플레이어들이 게임에서 승리합니다.","star":true},{"id":"11007a","name":"캉의 도래","en":"Kang's Arrival","type":"main","enc":true,"set":"Kang","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 캉 (I), 각 캉 (II), 캉 (III). 캉 및 일반 조우 세트. 모듈식 조우 세트 1개 <i>(시간).</i>\n<b>사전 준비</b>: 각 캉 (II), 캉 (III), 캉의 지배 부가 음모를 따로 놓아둡니다. 각 플레이어의 의무 카드를 게임에서 제거합니다. 조우 덱을 섞습니다."},{"id":"11007b","name":"캉의 도래","en":"Kang's Arrival","type":"main","enc":true,"set":"Kang","unique":false,"start":0,"target":7,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 플레이어에게 조우 카드를 1장씩 나누어 줍니다.\n<b>이 스테이지가 완료되면, 플레이어들은 게임에서 패배합니다.</b>"},{"id":"11008a","name":"시간의 지배자","en":"The Master of Time","type":"main","enc":true,"set":"Kang","unique":false,"stage":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 플레이 영역에 있는 부가 음모마다 이 카드에 가속 토큰 1개를 놓고, 그러고 나서 각 부가 음모를 버립니다. 각 플레이어는 차례 순서대로 무작위 스테이지 3A를 하나씩 공개합니다. 사용하지 않은 스테이지 3 음모를 모두 게임에서 제거합니다."},{"id":"11008b","name":"시간의 지배자","en":"The Master of Time","type":"main","enc":true,"set":"Kang","unique":false,"stage":2,"tr":[],"traits":[],"text":"<b>강제 난입</b>: 가속 토큰이 다른 음모에 놓이려 할 때, 대신 이 카드에 놓습니다.\n<b>다른 게임 영역이 남아 있지 않는 한, 플레이어들은 이 게임 영역에 합류할 수 없습니다. 모든 플레이어가 이 게임 영역에 합류하면, 스테이지 4A로 진행합니다.</b>"},{"id":"11009a","name":"크로노폴리스","en":"The Chronopolis","type":"main","enc":true,"set":"Kang","unique":false,"stage":3,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신만의 게임 영역을 만들고 이 음모를 그곳에 놓습니다. 캉 (이모터스)을 그 게임 영역에 추가하고 자신에게 조우 카드 1장을 나누어 줍니다."},{"id":"11009b","name":"크로노폴리스","en":"The Chronopolis","type":"main","enc":true,"set":"Kang","unique":false,"start":0,"target":9,"esc":1,"stage":3,"tr":[],"traits":[],"text":"<b>강제 반응</b>: 이 스테이지가 완료된 후, 따로 놓아둔 캉의 지배 1장을 스테이지 4A 밑에 뒷면으로 놓습니다. 페이즈가 끝날 때, 캉 (이모터스)과 이 스테이지를 게임에서 제거하고 당신의 게임 영역을 다른 게임 영역과 합칩니다.\n<b>이 스테이지에 있는 모든 플레이어가 격파되면, 이 스테이지는 완료됩니다.</b>"},{"id":"11010a","name":"피할 수 없는 운명","en":"Inexorable Fate","type":"main","enc":true,"set":"Kang","unique":false,"stage":3,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신만의 게임 영역을 만들고 이 음모를 그곳에 놓습니다. 캉 (아이언 래드)를 그 게임 영역에 추가하고 자신에게 조우 카드 1장을 나누어 줍니다."},{"id":"11010b","name":"피할 수 없는 운명","en":"Inexorable Fate","type":"main","enc":true,"set":"Kang","unique":false,"start":1,"target":9,"esc":1,"stage":3,"tr":[],"traits":[],"text":"<b>강제 반응</b>: 이 스테이지가 완료된 후, 따로 놓아둔 캉의 지배 1장을 스테이지 4A 밑에 뒷면으로 놓습니다. 페이즈가 끝날 때, 캉 (아이언 래드)와 이 스테이지를 게임에서 제거하고 당신의 게임 영역을 다른 게임 영역과 합칩니다.\n<b>이 스테이지에 있는 모든 플레이어가 격파되면, 이 스테이지는 완료됩니다.</b>"},{"id":"11011a","name":"라마-투트의 왕국","en":"The Realm of Rama-Tut","type":"main","enc":true,"set":"Kang","unique":false,"stage":3,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신만의 게임 영역을 만들고 이 음모를 그곳에 놓습니다. 캉 (라마-투트)를 그 게임 영역에 추가하고 자신에게 조우 카드 1장을 나누어 줍니다."},{"id":"11011b","name":"라마-투트의 왕국","en":"The Realm of Rama-Tut","type":"main","enc":true,"set":"Kang","unique":false,"start":1,"target":9,"esc":1,"stage":3,"tr":[],"traits":[],"text":"<b>강제 반응</b>: 이 스테이지가 완료된 후, 따로 놓아둔 캉의 지배 1장을 스테이지 4A 밑에 뒷면으로 놓습니다. 페이즈가 끝날 때, 캉 (라마-투트)와 이 스테이지를 게임에서 제거하고 당신의 게임 영역을 다른 게임 영역과 합칩니다.\n<b>이 스테이지에 있는 모든 플레이어가 격파되면, 이 스테이지는 완료됩니다.</b>"},{"id":"11012a","name":"현재와 미래의 전쟁","en":"The Present Future War","type":"main","enc":true,"set":"Kang","unique":false,"stage":3,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신만의 게임 영역을 만들고 이 음모를 그곳에 놓습니다. 캉 (스칼렛 센추리온)을 그 게임 영역에 추가하고 자신에게 조우 카드 1장을 나누어 줍니다."},{"id":"11012b","name":"현재와 미래의 전쟁","en":"The Present Future War","type":"main","enc":true,"set":"Kang","unique":false,"start":2,"target":9,"esc":1,"stage":3,"tr":[],"traits":[],"text":"<b>강제 반응</b>: 이 스테이지가 완료된 후, 따로 놓아둔 캉의 지배 1장을 스테이지 4A 밑에 뒷면으로 놓습니다. 페이즈가 끝날 때, 캉 (스칼렛 센추리온)과 이 스테이지를 게임에서 제거하고 당신의 게임 영역을 다른 게임 영역과 합칩니다.\n<b>이 스테이지에 있는 모든 플레이어가 격파되면, 이 스테이지는 완료됩니다.</b>"},{"id":"11013a","name":"캉의 분노","en":"Kang's Wrath","type":"main","enc":true,"set":"Kang","unique":false,"stage":4,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 캉 (III)을 공개해 게임 영역에 추가합니다. 이 스테이지 밑에 뒷면으로 놓인 각 캉의 지배를 공개합니다."},{"id":"11013b","name":"캉의 분노","en":"Kang's Wrath","type":"main","enc":true,"set":"Kang","unique":false,"start":0,"target":10,"targetStar":true,"esc":1,"escStar":true,"stage":4,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 플레이어는 조우 덱, 조우 버린 더미, 따로 놓아둔 영역에서 자신의 숙적 하수인을 찾아 자신과 교전 중인 채로 플레이 영역에 내려놓습니다. 조우 덱을 섞습니다.\n<b>이 스테이지가 완료되면, 플레이어들은 게임에서 패배합니다.</b>"},{"id":"11014","name":"시간 방어막","en":"Temporal Shield","type":"attachment","enc":true,"set":"Kang","unique":false,"boost":1,"tr":["TECH"],"traits":["과학"],"text":"캉에게 장착합니다.\n<b>강제 난입</b>: 캉이 공격받을 때, 시간 방어막을 버림 → 이 공격의 모든 피해를 방지하고 공격자에게 피해 1점을 입힘. (공격마다 최대 1장.)"},{"id":"11015","name":"미래 무기","en":"Future Weapon","type":"attachment","enc":true,"set":"Kang","unique":false,"boost":2,"plus":{"atk":2},"tr":["TECH","WEAPON"],"traits":["과학","무기"],"text":"캉에게 장착합니다.\n[star] <b>강제 난입</b>: 캉이 공격할 때, 그 공격은 압살을 얻습니다. 이 공격이 히어로에게 피해를 입히면, 그 히어로는 기절합니다. 이 공격 후, 미래 무기를 버립니다.","star":true},{"id":"11016","name":"시간 속에 갇히다","en":"Frozen in Time","type":"attachment","enc":true,"set":"Kang","unique":false,"tr":["TEMPORAL"],"traits":["시간"],"text":"당신의 아이덴티티에 장착합니다.\n<b>강제 난입</b>: 장착된 캐릭터가 준비하려 할 때, 대신 이 카드를 버립니다.\n<hr />\n[star] <b>강화</b>: 당신의 아이덴티티에 장착합니다.","star":true,"boostStar":true},{"id":"11017","name":"매크로봇","en":"Macrobots","type":"minion","enc":true,"set":"Kang","unique":false,"hp":4,"atk":2,"sch":1,"retaliate":1,"tr":["ROBOT","TEMPORAL"],"guard":1,"traits":["로봇","시간"],"text":"경호. 반격 1.\n<hr />\n[star] <b>강화</b>: 캉에게 강인함 상태 카드를 줍니다.","star":true,"boostStar":true},{"id":"11018","name":"약화","en":"Weakened","type":"obligation","enc":true,"set":"Kang","unique":false,"boost":2,"tr":["TEMPORAL"],"traits":["시간"],"text":"<b>강제 반응</b>: 당신이 히어로 기본 기능을 사용한 후, 피해 1점을 입습니다.\n<b>일상 행동</b>: 당신의 손에서 [physical] 자원 카드 1장을 버림 → 이 의무 카드를 버림."},{"id":"11019","name":"도둑맞은 기억","en":"Stolen Memories","type":"obligation","enc":true,"set":"Kang","unique":false,"boost":2,"tr":["TEMPORAL"],"traits":["시간"],"text":"<b>공개될 때</b>: 당신의 덱 맨 위 카드 8장을 이 카드 밑에 뒷면으로 놓습니다.\n<b>일상 행동</b>: 당신의 손에서 [mental] 자원 카드 1장을 버림 → 이 의무 카드를 버림. <i>(이 의무 카드 밑에 뒷면으로 놓인 카드를 모두 버립니다.)</i>"},{"id":"11020","name":"능력 상실","en":"Depowered","type":"obligation","enc":true,"set":"Kang","unique":false,"boost":2,"tr":["TEMPORAL"],"traits":["시간"],"text":"당신은 히어로 전용 카드를 플레이할 수 없습니다.\n<b>일상 행동</b>: 당신의 손에서 히어로 전용 카드 1장을 버림 → 이 의무 카드를 버림."},{"id":"11021","name":"시간 여행 소동","en":"Time-Travel Hijinks","type":"obligation","enc":true,"set":"Kang","unique":false,"boost":2,"tr":["TEMPORAL"],"traits":["시간"],"text":"<b>공개될 때</b>: 당신이 조종하는 카드 중 자원 비용이 가장 높은 카드를 버리고, 그러고 나서 그 카드를 이 카드 밑에 뒷면으로 놓습니다.\n<b>일상 행동</b>: 당신의 손에서 [energy] 자원 카드 1장을 버림 → 이 의무 카드를 버림.<i>(이 의무 카드 밑에 뒷면으로 놓인 카드를 모두 버립니다.)</i>"},{"id":"11022","name":"오염된 시간의 흐름","en":"Corrupted Timestream","type":"side","enc":true,"set":"Kang","unique":false,"boost":2,"start":2,"tr":[],"traits":[],"text":"플레이어들은 의무 카드의 \"<b>일상 행동</b>\" 능력을 격발할 수 없습니다.\n<b>공개될 때</b>: 각 플레이어는 자신의 손에서 무작위로 카드 1장을 버리거나, 이 카드에 위협을 2만큼 놓아야 합니다."},{"id":"11023","name":"캉의 지배","en":"Kang's Dominion","type":"side","enc":true,"set":"Kang","unique":false,"boost":3,"start":3,"startStar":true,"tr":[],"traits":[],"text":"캉은 피해를 입을 수 없습니다.\n<b>격파될 때</b>: 이 음모를 격파한 플레이어에게 조우 카드 1장을 나누어 줍니다."},{"id":"11024","name":"발이 묶임","en":"Pinned Down","type":"side","enc":true,"set":"Kang","unique":false,"boost":2,"start":2,"tr":[],"crisis":1,"traits":[],"text":"<b>공개될 때</b>: 플레이 영역에 있는 의무 카드마다 이 카드에 위협을 2만큼 놓습니다."},{"id":"11025","name":"난동","en":"Rampage","type":"side","enc":true,"set":"Kang","unique":false,"boost":3,"start":4,"accel":1,"tr":[],"traits":[],"text":"<b>격파될 때</b>: 하수인이 버려질 때까지 조우 덱 맨 위에서부터 카드를 버립니다. 그 하수인을 이 음모를 격파한 플레이어와 교전 중인 채로 플레이 영역에 내려놓습니다."},{"id":"11026","name":"에너지 폭발","en":"Energy Blast","type":"treachery","enc":true,"set":"Kang","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때(일상)</b>: 당신이 조종하는 동료나 지원 카드 하나를 버립니다. 그럴 수 없다면, 이 카드는 쇄도를 얻습니다.\n<b>공개될 때(히어로)</b>: 캉이 당신을 공격합니다."},{"id":"11027","name":"조작된 시간의 흐름","en":"Manipulated Timestream","type":"treachery","enc":true,"set":"Kang","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신의 손에서 이벤트를 모두 버립니다. 이렇게 버려진 이벤트가 없다면, 이 카드는 쇄도를 얻습니다."},{"id":"11028","name":"시간 여행 전술","en":"Time-Travel Tactics","type":"treachery","enc":true,"set":"Kang","unique":false,"boost":1,"surge":1,"tr":[],"traits":[],"text":"쇄도.\n<b>공개될 때</b>: 각 플레이어는 자신의 플레이 영역에 있는 의무 카드마다 간접 피해 1점을 입습니다.\n<hr />\n[star] <b>강화</b>: 당신의 플레이 영역에 있는 의무 카드마다 이 카드는 [boost]를 얻습니다.","star":true,"boostStar":true},{"id":"11029","name":"과거의 책략","en":"Past Machinations","type":"treachery","enc":true,"set":"Kang","unique":false,"boost":3,"tr":[],"incite":1,"traits":[],"text":"진척 1. <i>(이 카드가 공개되면, 주요 음모에 위협을 1만큼 놓습니다.)</i>\n<b>공개될 때</b>: 각 플레이어는 조우 덱과 조우 버린 더미에서 서로 다른 의무 카드를 하나씩 찾아 공개합니다.\n조우 덱을 섞습니다."},{"id":"11030","name":"고대 전사","en":"Ancient Warrior","type":"minion","enc":true,"set":"Temporal","unique":false,"hp":2,"atk":2,"sch":1,"tr":["SOLDIER","TEMPORAL"],"quickstrike":1,"traits":["군인","시간"],"text":"속공.\n<hr />\n[star] <b>강화</b>: 당신은 기절합니다.","star":true,"boostStar":true},{"id":"11031","name":"치타우리 군인","en":"Chitauri Soldier","type":"minion","enc":true,"set":"Temporal","unique":false,"hp":3,"atk":1,"sch":1,"boost":1,"tr":["SOLDIER","TEMPORAL"],"traits":["군인","시간"],"text":"[star] <b>강제 난입</b>: 치타우리 군인이 당신을 공격할 때, 조우 덱 맨 위 카드를 버림 → 그 카드의 강화 아이콘 수만큼 간접 피해를 입음.","star":true},{"id":"11032","name":"티라노사우루스 렉스","en":"Tyrannosaurus Rex","type":"minion","enc":true,"set":"Temporal","unique":false,"hp":6,"atk":3,"sch":0,"boost":3,"tr":["CREATURE","TEMPORAL"],"toughness":1,"traits":["괴수","시간"],"text":"강인.\n[star] 티라노사우루스 렉스의 공격은 관통을 얻습니다.","star":true},{"id":"11033","name":"시간 포털","en":"Time Portal","type":"side","enc":true,"set":"Temporal","unique":false,"boost":2,"start":2,"startStar":true,"hazard":1,"tr":[],"traits":[],"text":"<b>강제 난입</b>: 이 음모가 격파될 때, 이 음모를 버리는 대신 조우 덱에 섞어 넣습니다."},{"id":"11034","name":"캉 (정복자)","en":"* Kang (The Conqueror)","type":"villain","enc":true,"set":"Expert Kang","unique":true,"hp":15,"hpStar":true,"atk":3,"sch":1,"stage":1,"tr":["TEMPORAL"],"toughness":1,"traits":["시간"],"text":"강인.\n[star] <b>강제 난입</b>: 캉이 당신을 공격할 때, 주요 음모에 위협을 1만큼 놓거나, 그가 이 공격에 대해 공격 +2를 받는 것 중 하나를 선택합니다.\n<b>격파될 때</b>: 페이즈가 끝날 때 주요 음모를 스테이지 2로 진행합니다.","star":true},{"id":"11035","name":"캉 (이모터스)","en":"* Kang (Immortus)","type":"villain","enc":true,"set":"Expert Kang","unique":true,"hp":22,"atk":2,"sch":3,"stage":2,"tr":["TEMPORAL"],"toughness":1,"traits":["시간"],"text":"강인.\n하수인이 플레이 영역에 있는 동안 이 빌런은 피해를 입을 수 없습니다.\n<b>격파될 때</b>: 크로노폴리스를 게임에서 제거합니다. 페이즈가 끝날 때, 다른 게임 영역에 합류합니다."},{"id":"11036","name":"캉 (아이언 래드)","en":"* Kang (Iron Lad)","type":"villain","enc":true,"set":"Expert Kang","unique":true,"hp":22,"atk":3,"sch":2,"stage":2,"retaliate":1,"tr":["TEMPORAL"],"toughness":1,"traits":["시간"],"text":"반격 1. 강인.\n<b>격파될 때</b>: 피할 수 없는 운명을 게임에서 제거합니다. 페이즈가 끝날 때, 다른 게임 영역에 합류합니다."},{"id":"11037","name":"캉 (라마-투트)","en":"* Kang (Rama-Tut)","type":"villain","enc":true,"set":"Expert Kang","unique":true,"hp":22,"atk":3,"sch":2,"stage":2,"tr":["TEMPORAL"],"toughness":1,"traits":["시간"],"text":"강인.\n[star] 이 빌런은 플레이 영역에 있는 의무 카드마다 공격 +1을 받습니다.\n<b>격파될 때</b>: 라마-투트의 왕국을 게임에서 제거합니다. 페이즈가 끝날 때, 다른 게임 영역에 합류합니다.","star":true},{"id":"11038","name":"캉 (스칼렛 센추리온)","en":"* Kang (Scarlet Centurion)","type":"villain","enc":true,"set":"Expert Kang","unique":true,"hp":22,"atk":4,"sch":1,"stage":2,"tr":["TEMPORAL"],"toughness":1,"traits":["시간"],"text":"강인.\n[star] 이 빌런의 공격은 관통을 얻습니다.\n<b>격파될 때</b>: 현재와 미래의 전쟁을 게임에서 제거합니다. 페이즈가 끝날 때, 다른 게임 영역에 합류합니다.","star":true},{"id":"11039","name":"캉 (정복자)","en":"* Kang (The Conqueror)","type":"villain","enc":true,"set":"Expert Kang","unique":true,"hp":25,"hpStar":true,"atk":3,"sch":3,"stage":3,"tr":["TEMPORAL"],"toughness":1,"traits":["시간"],"text":"강인.\n[star] <b>강제 난입</b>: 캉이 당신을 공격할 때, 주요 음모에 위협을 1만큼 놓거나, 그가 이 공격에 대해 공격 +2를 받는 것 중 하나를 선택합니다.\n<b>격파될 때</b>: 플레이어들이 게임에서 승리합니다.","star":true},{"id":"11040","name":"아포크리퍼스","en":"* Apocryphus","type":"minion","enc":true,"set":"Anachronauts","unique":true,"hp":4,"atk":3,"sch":1,"tr":["ELITE","TEMPORAL"],"traits":["간부","시간"],"text":"<b>공개될 때</b>: 당신이 조종하는 동료나 지원 카드 하나를 버립니다.\n<hr />\n[star] <b>강화</b>: 당신이 조종하는 캐릭터 하나를 소진합니다. 이 적에게 강화 카드 1장을 추가로 줍니다.","star":true,"boostStar":true},{"id":"11041","name":"데스헌트 9000","en":"* Deathunt 9000","type":"minion","enc":true,"set":"Anachronauts","unique":true,"hp":6,"atk":1,"sch":1,"tr":["ELITE","TEMPORAL"],"toughness":1,"villainous":1,"traits":["간부","시간"],"text":"강인. 악당. <i>(이 하수인이 활성화할 때, 그 하수인에게 강화 카드 1장을 줍니다.)</i>\n<hr />\n[star] <b>강화</b>: 이 적에게 강인함 상태 카드와 강화 카드 1장을 추가로 줍니다.","star":true,"boostStar":true},{"id":"11042","name":"래스턴 경","en":"* Sir Raston","type":"minion","enc":true,"set":"Anachronauts","unique":true,"hp":6,"atk":2,"sch":1,"retaliate":1,"tr":["ELITE","TEMPORAL"],"guard":1,"traits":["간부","시간"],"text":"경호. 반격 1.\n<hr />\n[star] <b>강화</b>: 피해 1점을 입습니다. 이 적에게 강화 카드 1장을 추가로 줍니다.","star":true,"boostStar":true},{"id":"11043","name":"터미네이트릭스","en":"* Terminatrix","type":"minion","enc":true,"set":"Anachronauts","unique":true,"hp":5,"atk":2,"sch":2,"tr":["ELITE","TEMPORAL"],"quickstrike":1,"traits":["간부","시간"],"text":"속공.\n[star] 터미네이트릭스의 공격은 관통을 얻습니다.\n<hr />\n[star] <b>강화</b>: 이 적에게 강화 카드 2장을 추가로 줍니다.","star":true,"boostStar":true},{"id":"11044","name":"와일드런","en":"* Wildrun","type":"minion","enc":true,"set":"Anachronauts","unique":true,"hp":5,"atk":2,"sch":1,"tr":["ELITE","TEMPORAL"],"traits":["간부","시간"],"text":"<b>공개될 때</b>: 당신의 손에서 무작위로 카드 1장을 버립니다.\n<hr />\n[star] <b>강화</b>: 당신의 손에서 무작위로 카드 1장을 버립니다. 이 적에게 강화 카드 1장을 추가로 줍니다.","star":true,"boostStar":true},{"id":"11045","name":"아나크로노츠","en":"The Anachronauts","type":"side","enc":true,"set":"Anachronauts","unique":false,"boost":3,"start":3,"startStar":true,"hazard":1,"tr":[],"traits":[],"text":"<b>격파될 때</b>: 조우 버린 더미에 있는 각 [[시간]] 카드를 조우 덱에 섞어 넣습니다."},{"id":"11046","name":"캉의 선택받은 자","en":"Kang's Chosen","type":"treachery","enc":true,"set":"Anachronauts","unique":false,"boost":2,"tr":[],"incite":1,"traits":[],"text":"진척 1<i>(이 카드가 공개되면, 주요 음모에 위협을 1만큼 놓습니다).</i>\n<b>공개될 때</b>: [[시간]] 하수인이 버려질 때까지 조우 덱 맨 위에서부터 카드를 버립니다. 그 하수인을 공개합니다."},{"id":"11047","name":"캉 (시간의 지배자)","en":"* Kang (Master of Time)","type":"minion","enc":true,"set":"Master of Time","unique":true,"hp":6,"atk":1,"sch":1,"boost":2,"tr":["ELITE","TEMPORAL"],"toughness":1,"villainous":1,"traits":["간부","시간"],"text":"강인. 악당. <i>(이 하수인이 활성화할 때, 그 하수인에게 강화 카드 1장을 줍니다.)</i>\n캉 (시간의 지배자)은 당신의 플레이 영역에 있는 의무 카드마다 음모 +1과 공격 +1을 받습니다."},{"id":"11048","name":"시간 이탈 군인","en":"Time-Displaced Soldier","type":"minion","enc":true,"set":"Master of Time","unique":false,"hp":3,"atk":2,"sch":1,"surge":1,"tr":["ELITE","TEMPORAL"],"incite":1,"traits":["간부","시간"],"text":"진척 1. 쇄도.\n<hr />\n[star] <b>강화</b>: 당신에게 뒷면 조우 카드 1장을 나누어 줍니다.","star":true,"boostStar":true},{"id":"11049","name":"캉에 대한 공포","en":"Fear of Kang","type":"obligation","enc":true,"set":"Master of Time","unique":false,"boost":2,"tr":["TEMPORAL"],"traits":["시간"],"text":"당신은 캉을 공격할 수 없습니다.\n<b>일상 행동</b>: 당신의 손에서 무작위로 카드 1장을 버림 → 이 의무 카드를 버림."},{"id":"11050","name":"세기의 빛 구체","en":"Light of Centuries Sphere","type":"side","enc":true,"set":"Master of Time","unique":false,"boost":3,"start":3,"startStar":true,"hazard":1,"tr":[],"traits":[],"text":"<b>격파될 때</b>: 하수인이 버려질 때까지 조우 덱 맨 위에서부터 카드를 버립니다. 그 하수인을 이 음모를 격파한 플레이어와 교전 중인 채로 플레이 영역에 내려놓습니다."},{"id":"11051","name":"고대의 원한","en":"Ancient Grudge","type":"treachery","enc":true,"set":"Master of Time","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 캉 (시간의 지배자)이 당신을 상대로 활성화합니다. 캉 (시간의 지배자)이 플레이 영역에 없다면, 조우 덱과 조우 버린 더미에서 캉 (시간의 지배자)을 찾아 당신과 교전 중인 채로 플레이 영역에 내려놓습니다. 조우 덱을 섞습니다."}]});
